INSERT INTO combat_effect_definition VALUES ('fork_star:upgradestar_pack_fork_elyms:1', 'fork_star', 'upgradestar_pack_fork_elyms', 'description_parameters', 'equipped_fork', '攻击力提升<lv>{0}</>。' || char(10) || '' || char(10) || '装备者释放「极轨终结」后，若造成3次「追加攻击伤害」，则全队获得<lv>{1}</>无视防御，装备者额外获得<lv>{2}</>无视防御，持续<lv>{3}</>秒，重复触发刷新持续时间，该效果队伍内唯一。' || char(10) || '' || char(10) || '装备者释放变轨技能时全队无视敌人<lv>{4}</>光属性异能抗性，持续<lv>{5}</>秒，重复触发刷新持续时间，该效果队伍内唯一。' || char(10) || '' || char(10) || '装备者在进入战斗时直接触发以上所有效果。', '[{"is_percent":true,"name_id":"buff_Elyms_AtkUp","ordinal":0,"value":0.15},{"is_percent":true,"name_id":"buff_Elyms_DefIgnore","ordinal":1,"value":0.12},{"is_percent":true,"name_id":"buff_Elyms_DefIgnore2","ordinal":2,"value":0.1},{"is_percent":false,"name_id":"buff_Elyms_Up_Dur","ordinal":3,"value":20.0},{"is_percent":true,"name_id":"buff_Elyms_Penetrate","ordinal":4,"value":0.08},{"is_percent":false,"name_id":"buff_Elyms_Penetrate_Dur","ordinal":5,"value":20.0}]', 1, 1100146);
