INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect1', 'character_awaken', '1090:Effect1', 'Awaken_Effect', 'awakening_unlocked', '释放「极轨终结：一如昨日光景」后，依据释放前累计消耗的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>层数，每消耗过<NumGreen>1</>层，使全队角色的暴击伤害提高<NumGreen>10%</>，持续<NumGreen>20</>秒。重复触发时，刷新该增益的效果和持续时间，并清空<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>累计消耗层数。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level1/Buff_Elyms_Level1.Buff_Elyms_Level1_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect2', 'character_awaken', '1090:Effect2', 'Awaken_Effect', 'awakening_unlocked', '「极轨终结：一如昨日光景」伤害的倍率提升<NumGreen>30%</>。' || char(10) || '' || char(10) || '释放「变轨技能：对你说再见」时，每消耗<NumGreen>1</>层<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，本次技能造成的伤害无视目标<NumGreen>5%</>防御。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level2/Buff_Elyms_Level2.Buff_Elyms_Level2_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect3', 'character_awaken', '1090:Effect3', 'Awaken_Effect', 'awakening_unlocked', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>从<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>后，获得<NumGreen>3</>层<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>。' || char(10) || '' || char(10) || '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>可叠加，上限<NumGreen>4</>层。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level3/Buff_Elyms_Level3.Buff_Elyms_Level3_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect4', 'character_awaken', '1090:Effect4', 'Awaken_Effect', 'awakening_unlocked', '曳尔沐在编队内且存活时，全队暴击伤害提升<NumGreen>20%</>。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level4/Buff_Elyms_Level4.Buff_Elyms_Level4_C","SubPathString":""},"bReliveNeedAddAgain":true}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect5', 'character_awaken', '1090:Effect5', 'Awaken_Effect', 'awakening_unlocked', '「变轨技能：离去的人们」伤害的倍率提升<NumGreen>100%</>。' || char(10) || '' || char(10) || '进入战斗时，曳尔沐的「环合值」为<NumGreen>100</>点，此效果有<NumGreen>30</>秒冷却且单场战斗中最多生效<NumGreen>1</>次。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level5/Buff_Elyms_Level5.Buff_Elyms_Level5_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:Effect6', 'character_awaken', '1090:Effect6', 'Awaken_Effect', 'awakening_unlocked', '释放「极轨终结：一如昨日光景」后，依据释放前累计消耗的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>层数，每消耗过<NumGreen>1</>层，使曳尔沐造成的追加攻击伤害提升<NumGreen>25%</>，持续<NumGreen>20</>秒。重复触发时，刷新该增益的效果和持续时间，并清空<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>累计消耗层数。', '{"gameplay_effect_ids":[],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/Level6/Buff_Elyms_Level6.Buff_Elyms_Level6_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:resonance_3', 'character_awaken', '1090:resonance_3', 'Awaken_Resonance', 'awakening_unlocked', '「普通攻击」、「变轨技能」、「极轨终结」的技能等级提高<NumGreen>1</>级。' || char(10) || '' || char(10) || '释放「援护技：我在」或「变轨技能：不连续的存在」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则直接增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>，并依次触发<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>、<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>的相关效果。<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>时，可立即释放「变轨技能：对你说再见」。', '{"gameplay_effect_ids":[],"modify_data":[{"SkillLevel":1,"SkillName":"GA_Elyms_Melee"},{"SkillLevel":1,"SkillName":"GA_Elyms_Skill"},{"SkillLevel":1,"SkillName":"GA_Elyms_UltraSkill"},{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/LevelExtra/Buff_Elyms_LevelExtra3.Buff_Elyms_LevelExtra3_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
INSERT INTO combat_effect_definition VALUES ('character_awaken:1090:resonance_6', 'character_awaken', '1090:resonance_6', 'Awaken_Resonance', 'awakening_unlocked', '曳尔沐在编队内且存活时，全队角色造成的伤害无视目标<NumGreen>12%</>全属性抗性。' || char(10) || '' || char(10) || '「变轨技能：对你说再见」的最后一段命中目标时，若本次技能消耗了<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，则额外造成<NumGreen>1</>次<Guang>光属性异能伤害</>，当前「变轨技能：沉入电子梦」技能等级下的倍率为<NumGreen>{0}%*</><hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</><NumGreen>消耗层数</>。', '{"gameplay_effect_ids":["GE_Player_Elyms_Skill3Extra_Damage"],"modify_data":[{"Buff":{"AssetPathName":"/Game/Blueprints/Abilities/Player/Ability_090_Elyms/Upgrade/LevelExtra/Buff_Elyms_LevelExtra6.Buff_Elyms_LevelExtra6_C","SubPathString":""},"bReliveNeedAddAgain":false}]}', 1, 1100001);
