INSERT INTO fork_star_level VALUES ('upgradestar_pack_fork_elyms', 1, '「留声#重拨」', '攻击力提升<lv>{0}</>。' || char(10) || '' || char(10) || '装备者释放「极轨终结」后，若造成3次「追加攻击伤害」，则全队获得<lv>{1}</>无视防御，装备者额外获得<lv>{2}</>无视防御，持续<lv>{3}</>秒，重复触发刷新持续时间，该效果队伍内唯一。' || char(10) || '' || char(10) || '装备者释放变轨技能时全队无视敌人<lv>{4}</>光属性异能抗性，持续<lv>{5}</>秒，重复触发刷新持续时间，该效果队伍内唯一。' || char(10) || '' || char(10) || '装备者在进入战斗时直接触发以上所有效果。', 'gold:100', '[{"BuffObject":{"AssetPathName":"/Game/Blueprints/Abilities/Buff/Fork/Fork_Elyms/Buff_Fork_Elyms_Lv1.Buff_Fork_Elyms_Lv1_C","SubPathString":""},"IsGlobal":false,"bReliveNeedAddAgain":false}]', 1100146);
