INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 0, 'ADT_DES', '<Title>即时故障</>', '<Italic>即刻生效的奢望。</>' || char(10) || '' || char(10) || '曳尔沐的连接存在<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>的区别，信号强度为<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>时，曳尔沐操控「旧梦终端」，进行至多五段连续攻击，造成<Guang>光属性异能伤害</>。' || char(10) || '' || char(10) || '曳尔沐释放「普通攻击：即时故障」最后一段后，可在一定时间内直接激活「变轨技能：不连续的存在」。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee1_des', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>时进行最多<NumGreen>5</>段连续攻击，造成<Guang>光属性异能伤害</>。曳尔沐释放「普通攻击：即时故障」最后一段后，可在一定时间内直接激活「变轨技能：不连续的存在」。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 1, 'ADT_DES', '<Title>错频故障</>', '<Italic>历久弥新的遗憾。</>' || char(10) || '' || char(10) || '信号强度为<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>时，曳尔沐操控「旧梦终端」，进行至多三段连续攻击，造成<Guang>光属性异能伤害</>。' || char(10) || '' || char(10) || '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态下，曳尔沐释放「普通攻击：错频故障」最后一段后，可在一定时间内直接激活「变轨技能：对你说再见」。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee2_des', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>时进行最多<NumGreen>3</>段连续攻击，造成<Guang>光属性异能伤害</>。<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态下，曳尔沐释放「普通攻击：错频故障」最后一段后，可在一定时间内直接激活「变轨技能：对你说再见」。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 2, 'ADT_DES', '<Title>干扰故障</>', '<Italic>还是有些模糊呢……</>' || char(10) || '' || char(10) || '曳尔沐处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态时，在「普通攻击：即时故障」中长按普通攻击，可触发「普通攻击：干扰故障」，造成<Guang>光属性异能伤害</>。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee3_des', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>时，在「普通攻击：即时故障」中长按普攻，触发分支攻击，造成<Guang>光属性异能伤害</>。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 3, 'ADT_DES', '<Title>记忆锚点</>', '<Italic>让我们……重新回忆一次……</>' || char(10) || '' || char(10) || '任意<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>下，曳尔沐均可通过瞄准键使用「瞄准攻击：记忆锚点」，造成<Guang>光属性异能伤害</>。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee4_des', '任意<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>下均可按瞄准键发动瞄准攻击，造成<Guang>光属性异能伤害</>。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 4, 'ADT_DES', '<Title>坠落梦</>', '<Italic>又一次在梦中坠落。</>' || char(10) || '' || char(10) || '曳尔沐滞空时点按普攻，落地后造成<NumGreen>1</>次范围性的<Guang>光属性异能伤害</>，伤害随下落高度升高而提升，最高提升<NumGreen>1</>倍。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee5_des', '滞空时点按普攻，落地造成范围性<Guang>光属性异能伤害</>，伤害随下落高度提升，最高提升<NumGreen>1</>倍。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 5, 'ADT_DES', '<Title>好的！握手！</>', '<Italic>敬个礼！握握手！你是我的好朋友！</>' || char(10) || '' || char(10) || '曳尔沐触发极限闪避后点击普攻发动反击，造成<Guang>光属性异能伤害</>。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_PerfectEvade_des', '极限闪避后点击普攻发动反击，造成<Guang>光属性异能伤害</>。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Melee', 6, 'ADT_AFFIX', NULL, '<Italic>观察笔记#■■■</>' || char(10) || '' || char(10) || '<Italic>研究对象：即时通讯</>' || char(10) || '' || char(10) || '' || char(10) || '' || char(10) || '<Italic>由人类「想要即时得到回应」的欲望催生。若发信者输入「想要倾诉的话」，便能从另一个发信者处得到回应。</>' || char(10) || '' || char(10) || '<Italic>该类连接稳定性差，接收方所面向的对象为发信者的数字化身，能否得到回应却取决于对应的人类本体。</>' || char(10) || '' || char(10) || '<Italic>针对被试#■■■的实验表明，即时性的短接故障将数字化身与本体分离，显著提高了双方的满意度。</>' || char(10) || '' || char(10) || '<Italic>该研究仍在持续进行。</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Melee_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive1', 0, 'ADT_DES', NULL, '<TextHLT>「盈蓄」强化</>：当前驻场角色获得终结能量时，全队角色的<Guang>光属性异能伤害</>提高<NumGreen>3.75%</>，持续<NumGreen>30</>秒，最多叠加<NumGreen>8</>层，重复触发刷新持续时间。' || char(10) || '' || char(10) || '<TextHLT>「延滞」强化</>：队伍中任意角色对目标施加「延滞」时，曳尔沐会在<NumGreen>7.5</>秒后对该目标追加一次「延滞」。该效果每<NumGreen>7</>秒至多触发一次，且通过该效果施加的「延滞」不会再次触发该效果。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_1_des', '<TextHLT>「盈蓄」强化</>：当前驻场角色获得终结能量时，全队角色的<Guang>光属性异能伤害</>提高<NumGreen>3.75%</>，持续<NumGreen>30</>秒，最多叠加<NumGreen>8</>层，重复触发刷新持续时间。' || char(10) || '' || char(10) || '<TextHLT>「延滞」强化</>：队伍中任意角色对目标施加「延滞」时，曳尔沐会在<NumGreen>7.5</>秒后对该目标追加一次「延滞」。该效果每<NumGreen>7</>秒至多触发一次，且通过该效果施加的「延滞」不会再次触发该效果。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive1', 1, 'ADT_AFFIX', NULL, '<Italic>「信号连接不够强力！让我来放大功率！」</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_1_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive2', 0, 'ADT_DES', NULL, '曳尔沐的暴击伤害提高<NumGreen>10%</>。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_2_des', '曳尔沐的暴击伤害提高<NumGreen>10%</>。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive2', 1, 'ADT_AFFIX', NULL, '<Italic>「大战之前，当然要补满状态啦！」</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_2_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive3', 0, 'ADT_DES', NULL, '若曳尔沐处于待机状态，有一定概率触发「在吗在吗」。曳尔沐会主动向你打招呼，送上准备好的小礼物，每天一份哦~！', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_3_des', '若曳尔沐处于待机状态，有一定概率触发「在吗在吗」。曳尔沐会主动向你打招呼，送上准备好的小礼物，每天一份哦~！', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Passive3', 1, 'ADT_AFFIX', NULL, '<Italic>「你去哪了？」</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Passive_3_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_QTE', 0, 'ADT_DES', NULL, '<Italic>在线状态！</>曳尔沐操控「旧梦终端」，造成<Guang>光属性异能伤害</>。' || char(10) || '' || char(10) || '曳尔沐在场时，释放「援护技：我在」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态；同时检索一定范围内的目标数量，自动切换「极轨终结：一如昨日光景」的对单/对群形态。' || char(10) || '' || char(10) || '「信号强度」从<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>时，获得增益效果<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，持续一定时间。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_QTE_des', '造成<Guang>光属性异能伤害</>。曳尔沐在场时，释放「援护技：我在」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态，并获得<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>；同时检索目标，切换「极轨终结：一如昨日光景」的对单/对群形态。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_QTE', 1, 'ADT_AFFIX', NULL, '<Italic>「想起我了吗？我一直都在。」</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_QTE_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Skill', 0, 'ADT_DES', '<Title>离去的人们</>', '<Italic>亦如将要到来之人。</>' || char(10) || '' || char(10) || '曳尔沐操控「旧梦终端」对范围目标造成<Guang>光属性异能伤害</>。' || char(10) || '' || char(10) || '若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则可在释放该技能后一定时间内直接激活「变轨技能：不连续的存在」。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Skill1_des', '造成范围性<Guang>光属性异能伤害</>。<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态时，释放「变轨技能：离去的人们」后，可在一定时间内直接激活「变轨技能：不连续的存在」。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Skill', 1, 'ADT_DES', '<Title>不连续的存在</>', '<Italic>绵延是过去的持续进展，它逐步地侵蚀着未来。</>' || char(10) || '' || char(10) || '曳尔沐对范围目标造成<Guang>光属性异能伤害</>。释放「变轨技能：不连续的存在」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态。同时自动检索一定范围内的目标数量，依此切换「极轨终结：一如昨日光景」的对群/对单形态。' || char(10) || '' || char(10) || '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>时，获得增益效果<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，持续一定时间。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Skill2_des', '造成范围性<Guang>光属性异能伤害</>。释放「变轨技能：不连续的存在」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态，并获得<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>；同时检索目标，切换「极轨终结：一如昨日光景」的对单/对群形态。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Skill', 2, 'ADT_DES', '<Title>对你说再见</>', '<Italic>未知的世界如盛夏蜃景，连你也是遥远的幻影。</>' || char(10) || '' || char(10) || '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态下，曳尔沐释放「普通攻击：错频故障」最后一段后，可在一定时间内直接激活「变轨技能：对你说再见」。' || char(10) || '' || char(10) || '曳尔沐对范围目标造成<Guang>光属性异能伤害</>。释放时消耗所有<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，并依据消耗层数提高本次技能的伤害倍率。' || char(10) || '' || char(10) || '释放后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态；同时检索一定范围内的目标数量，自动切换「极轨终结：一如昨日光景」的对单/对群形态。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Skill3_des', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态下，曳尔沐释放「普通攻击：错频故障」最后一段后，可在一定时间内直接激活「变轨技能：对你说再见」。造成范围性<Guang>光属性异能伤害</>。释放时消耗所有<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun2">「错视幻觉」</>，并依据消耗层数提高本次技能的伤害倍率；释放「变轨技能：对你说再见」后，若处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>状态，则增强至<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态；同时检索目标，切换「极轨终结：一如昨日光景」的对单/对群形态。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_Skill', 3, 'ADT_AFFIX', NULL, '<Italic>没有乐队，然而……我们可以听到乐声。</>' || char(10) || '' || char(10) || '<Italic>根本没有乐队！一切都是……录音。</>' || char(10) || '' || char(10) || '<Italic>根本没有&^%$#@!@#$%^&*&^%$#@!@#$%^&*&^%$#@!@#$%^&*&^%$#，一切都是</>' || char(10) || '' || char(10) || '<Italic>■■■■■■■■■■■■■■■■■■■■■■■</>' || char(10) || '' || char(10) || '' || char(10) || '' || char(10) || '<Italic>寂静……</>' || char(10) || '' || char(10) || '<Italic>寂静？</>' || char(10) || '' || char(10) || '<Italic>寂静。</>' || char(10) || '' || char(10) || '<Italic>我的朋友。</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_Skill_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_UltraSkill', 0, 'ADT_DES', NULL, '<Italic>我们每天度过的日常，其实也许是奇迹的延续。</>' || char(10) || '' || char(10) || '<Italic>你，又会在昨日光景中看到谁的掠影？</>' || char(10) || '' || char(10) || '' || char(10) || '' || char(10) || '曳尔沐的「极轨终结：一如昨日光景」存在对单/对群两种形态。' || char(10) || '' || char(10) || '处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>状态时，「极轨终结：一如昨日光景」默认为对群形态；' || char(10) || '' || char(10) || '处于<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>状态时，「极轨终结：一如昨日光景」会依据「变轨技能：不连续的存在」、「变轨技能：对你说再见」以及曳尔沐在场时释放的「援护技：我在」的目标检索结果，自动切换对应的对单/对群形态。' || char(10) || '' || char(10) || '「极轨终结：一如昨日光景」的伤害倍率依据释放时的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>确定。释放「极轨终结：一如昨日光景」或脱战后，<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>重置为<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>。' || char(10) || '' || char(10) || '' || char(10) || '' || char(10) || '释放「极轨终结：一如昨日光景」后，全队角色获得基于曳尔沐自身基础攻击力的攻击提升，同时全队角色造成的追加攻击伤害提升，持续一定时间。' || char(10) || '' || char(10) || '同时曳尔沐获得增益状态<TextHLT>「后台连线」</>，状态持续期间，若曳尔沐处于后台，则会自动触发协同攻击<TextHLT>「追忆」</>。' || char(10) || '' || char(10) || '协同攻击<TextHLT>「追忆」</>的对单/对群形态与此前释放的「极轨终结：一如昨日光景」相同，其伤害倍率依据该次「极轨终结：一如昨日光景」释放时的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>确定。' || char(10) || '' || char(10) || '<TextHLT>「追忆」</>造成的伤害视为追加攻击伤害。' || char(10) || '' || char(10) || '<TextHLT>「追忆」</>释放次数达到上限后，<TextHLT>「后台连线」</>状态结束。', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_UtraSkill_des', '<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>时释放对群形态的「极轨终结：一如昨日光景」；<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「中等信号」</>或<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「强信号」</>时按「变轨技能：不连续的存在」、「变轨技能：对你说再见」或曳尔沐在场时释放的「援护技：我在」的检索结果选择形态。「极轨终结：一如昨日光景」的伤害倍率依据释放时的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>确定。释放「极轨终结：一如昨日光景」或脱战后，<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>重置为<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「弱信号」</>。曳尔沐对目标造成<Guang>光属性异能伤害</>。释放「极轨终结：一如昨日光景」后，提升全队角色的攻击力和造成的追加攻击伤害。曳尔沐获得<TextHLT>「后台连线」</>，状态持续期间，若曳尔沐处于后台，则自动触发协同攻击<TextHLT>「追忆」</>。协同攻击<TextHLT>「追忆」</>的对单/对群形态与此前释放的「极轨终结：一如昨日光景」相同，其伤害倍率依据该次「极轨终结：一如昨日光景」释放时的<hot textstyle="TextEXPL" param="nouns&Elyms_propNoun1">「信号强度」</>确定。<TextHLT>「追忆」</>释放次数达到上限后，<TextHLT>「后台连线」</>状态结束。', NULL, NULL, '[]');
INSERT INTO gameplay_ability_description VALUES ('GA_Elyms_UltraSkill', 1, 'ADT_AFFIX', NULL, '<Italic>再平凡不过的一天，一起打开还没通关的游戏，一起消磨时间，被无关紧要的小事逗笑，去常吃的小店，在路上告别，约定下一次再见。</>' || char(10) || '' || char(10) || '<Italic>重复发生的日常，一如昨日光景。</>' || char(10) || '' || char(10) || '' || char(10) || '' || char(10) || '<Italic>一切都未曾改变，一切都不会改变，只要这样就好……</>' || char(10) || '' || char(10) || '<Italic>肯定请按1，肯定请按2，肯定请按3，肯定请按4，肯定请按5，肯定请按6，肯定请按7，肯定请按8，肯定请按9，肯定请按0，肯定请按#。</>', '/Game/Text/PlayerSkillDes/Elyms_SkillDes.Elyms_SkillDes', 'GA_Elyms_UltraSkill_background', NULL, NULL, NULL, '[]');
INSERT INTO gameplay_ability_level_hint VALUES ('GA_Elyms_Melee', 0, NULL, '「即时故障」一段伤害倍率', '{0}%*2', NULL, 'UseGEDamageType', '["GE_Player_Elyms_Melee1_Damage"]', '[]', '[]');
INSERT INTO gameplay_ability_level_hint VALUES ('GA_Elyms_Melee', 1, NULL, '「即时故障」二段伤害倍率', '{0}%*2', NULL, 'UseGEDamageType', '["GE_Player_Elyms_Melee2_Damage"]', '[]', '[]');
